-- Profile iplant-block-extraction-v1; SELECT only. Bind @EstateID, @FromDate, @ToDate and @Year.
SELECT YEAR(c.DDate) Year,b.BlockName,c.Type,cy.CropYieldCode,COUNT(*) Records,SUM(c.MilWeight)/1000.0 Tonnes,SUM(c.Bunches) Bunches FROM Checkroll.CropStatement c LEFT JOIN General.BlockMaster b ON b.BlockID=c.BlockID AND b.EstateID=c.EstateID LEFT JOIN General.CropYield cy ON cy.CropYieldID=c.CropYieldID WHERE c.EstateID=@EstateID GROUP BY YEAR(c.DDate),b.BlockName,c.Type,cy.CropYieldCode ORDER BY Year,b.BlockName,c.Type;
WITH w AS (SELECT DailyReceiptionDetID,COUNT(*) TeamRows,SUM(COALESCE(HarvestedNormal,0)+COALESCE(HarvestedBorongan,0)) Bunches,SUM(COALESCE(LooseFruitNormal,0)+COALESCE(LooseFruitBorongan,0)) LooseFruit,SUM(Ha) Ha FROM Checkroll.DailyReceptionWithTeam GROUP BY DailyReceiptionDetID)
SELECT YEAR(a.RDate) Year,MONTH(a.RDate) Month,COUNT(*) ReceptionRows,COUNT(DISTINCT r.BlockID) Blocks,COUNT(DISTINCT a.EmpID) Harvesters,SUM(CASE WHEN w.TeamRows IS NOT NULL THEN w.Bunches ELSE COALESCE(r.NActualBunches,0)+COALESCE(r.BActualBunches,0) END) HarvestedBunches,SUM(w.LooseFruit) TeamLooseFruit,SUM(w.Ha) TeamHa FROM Checkroll.DailyReceiption r JOIN Checkroll.DailyAttendance a ON a.DailyReceiptionID=r.DailyReceiptionID AND a.EstateID=r.EstateID LEFT JOIN w ON w.DailyReceiptionDetID=r.DailyReceiptionDetID WHERE r.EstateID=@EstateID GROUP BY YEAR(a.RDate),MONTH(a.RDate) ORDER BY Year,Month;
WITH w AS (SELECT DailyReceiptionDetID,COUNT(*) TeamRows,SUM(COALESCE(HarvestedNormal,0)+COALESCE(HarvestedBorongan,0)) Bunches FROM Checkroll.DailyReceptionWithTeam GROUP BY DailyReceiptionDetID)
SELECT YEAR(a.RDate) Year,b.BlockName,COUNT(*) ReceptionRows,COUNT(DISTINCT a.EmpID) Harvesters,SUM(CASE WHEN w.TeamRows IS NOT NULL THEN w.Bunches ELSE COALESCE(r.NActualBunches,0)+COALESCE(r.BActualBunches,0) END) HarvestedBunches FROM Checkroll.DailyReceiption r JOIN Checkroll.DailyAttendance a ON a.DailyReceiptionID=r.DailyReceiptionID AND a.EstateID=r.EstateID LEFT JOIN w ON w.DailyReceiptionDetID=r.DailyReceiptionDetID LEFT JOIN General.BlockMaster b ON b.BlockID=r.BlockID AND b.EstateID=r.EstateID WHERE r.EstateID=@EstateID GROUP BY YEAR(a.RDate),b.BlockName ORDER BY Year,b.BlockName;
SELECT YEAR(i.SIVDate) Year,c.STCategoryCode,c.STCategoryDescp,u.UOM,COUNT(*) Lines,COUNT(DISTINCT d.BlockID) Blocks,SUM(d.IssuedQty) IssuedQty,SUM(d.ReturnQty) ReturnQty,SUM(d.IssuedValue) GrossIssuedValue FROM Store.STIssueDetails d JOIN Store.STIssue i ON i.STIssueID=d.STIssueID AND i.EstateID=d.EstateID LEFT JOIN Store.STMaster s ON s.StockID=d.StockID AND s.EstateID=d.EstateID LEFT JOIN Store.STCategory c ON c.STCategoryID=s.STCategoryID AND c.EstateID=s.EstateID LEFT JOIN General.UOM u ON u.UOMID=s.UOMID WHERE d.EstateID=@EstateID AND i.Status='APPROVED' GROUP BY YEAR(i.SIVDate),c.STCategoryCode,c.STCategoryDescp,u.UOM ORDER BY Year,c.STCategoryCode,u.UOM;
SELECT YEAR(i.SIVDate) Year,b.BlockName,c.STCategoryDescp,s.StockCode,s.StockDesc,u.UOM,COUNT(*) Lines,SUM(d.IssuedQty) IssuedQty,SUM(d.ReturnQty) ReturnQty,SUM(d.IssuedValue) GrossIssuedValue FROM Store.STIssueDetails d JOIN Store.STIssue i ON i.STIssueID=d.STIssueID AND i.EstateID=d.EstateID JOIN Store.STMaster s ON s.StockID=d.StockID AND s.EstateID=d.EstateID JOIN Store.STCategory c ON c.STCategoryID=s.STCategoryID AND c.EstateID=s.EstateID LEFT JOIN General.UOM u ON u.UOMID=s.UOMID LEFT JOIN General.BlockMaster b ON b.BlockID=d.BlockID AND b.EstateID=d.EstateID WHERE d.EstateID=@EstateID AND i.Status='APPROVED' AND c.STCategoryCode IN ('ST04','ST12') GROUP BY YEAR(i.SIVDate),b.BlockName,c.STCategoryDescp,s.StockCode,s.StockDesc,u.UOM ORDER BY Year,b.BlockName,c.STCategoryDescp,s.StockCode;
SELECT a.AYear Year,a.AMonth Month,b.BlockName,c.Category,c.JDDescp,COUNT(*) Rows,SUM(c.HK) HK,SUM(c.OT) OT,SUM(c.DebitValue) Debit,SUM(c.CreditValue) Credit FROM dbo.CheckrollTemp c JOIN General.ActiveMonthYear a ON a.ActiveMonthYearID=c.ActiveMonthYear AND a.EstateID=c.Location LEFT JOIN General.BlockMaster b ON b.BlockID=c.Block AND b.EstateID=c.Location WHERE c.Location=@EstateID GROUP BY a.AYear,a.AMonth,b.BlockName,c.Category,c.JDDescp ORDER BY Year,Month,b.BlockName;
SELECT h.AYear Year,b.BlockName,h.ModID,h.LedgerType,COUNT(*) Lines,SUM(CASE WHEN d.DC='D' THEN d.Value ELSE 0 END) Debit,SUM(CASE WHEN d.DC='C' THEN d.Value ELSE 0 END) Credit FROM Accounts.JournalDetail d JOIN Accounts.LedgerAllModule h ON h.LedgerID=d.LedgerID AND h.EstateID=d.EstateID LEFT JOIN General.BlockMaster b ON b.BlockID=d.BlockID AND b.EstateID=d.EstateID WHERE d.EstateID=@EstateID GROUP BY h.AYear,b.BlockName,h.ModID,h.LedgerType ORDER BY Year,b.BlockName,h.ModID;
SELECT a.AYear Year,b.BlockName,v.UOM,d.Posted,COUNT(*) Lines,COUNT(DISTINCT d.VHID) Vehicles,SUM(d.KmHours) AllocatedKmHours,MIN(d.DistributionDT) FirstDate,MAX(d.DistributionDT) LastDate FROM Vehicle.VHDistribution d JOIN General.ActiveMonthYear a ON a.ActiveMonthYearID=d.ActiveMonthYearID AND a.EstateID=d.EstateID LEFT JOIN Vehicle.VHMaster v ON v.VHID=d.VHID AND v.EstateID=d.EstateID LEFT JOIN General.BlockMaster b ON b.BlockID=d.BlockID AND b.EstateID=d.EstateID WHERE d.EstateID=@EstateID GROUP BY a.AYear,b.BlockName,v.UOM,d.Posted ORDER BY Year,b.BlockName;
SELECT a.AYear Year,a.AMonth Month,COUNT(*) Rows,COUNT(DISTINCT d.BlockID) Blocks,SUM(d.Mandays) Mandays,SUM(d.Ha) ActivityHa,SUM(d.OT) OT FROM Checkroll.DailyActivityDistribution d JOIN General.ActiveMonthYear a ON a.ActiveMonthYearID=d.ActiveMonthYearID AND a.EstateID=d.EstateID WHERE d.EstateID=@EstateID GROUP BY a.AYear,a.AMonth ORDER BY Year,Month;
SELECT YEAR(a.RDate) Year,COUNT(*) AttendanceRows,COUNT(DISTINCT a.EmpID) Employees FROM Checkroll.DailyAttendance a WHERE a.EstateID=@EstateID GROUP BY YEAR(a.RDate) ORDER BY Year;
SELECT 'Reception without attendance' Issue,COUNT(*) Rows FROM Checkroll.DailyReceiption r WHERE r.EstateID=@EstateID AND NOT EXISTS(SELECT 1 FROM Checkroll.DailyAttendance a WHERE a.DailyReceiptionID=r.DailyReceiptionID AND a.EstateID=r.EstateID)
UNION ALL SELECT 'Reception duplicate attendance keys',COUNT(*) FROM (SELECT DailyReceiptionID FROM Checkroll.DailyAttendance WHERE EstateID=@EstateID GROUP BY DailyReceiptionID HAVING COUNT(*)>1) d
UNION ALL SELECT 'Duplicate block IDs',COUNT(*) FROM (SELECT BlockID FROM General.BlockMaster WHERE EstateID=@EstateID GROUP BY BlockID HAVING COUNT(*)>1) d
UNION ALL SELECT 'Duplicate ledger IDs',COUNT(*) FROM (SELECT LedgerID FROM Accounts.LedgerAllModule WHERE EstateID=@EstateID GROUP BY LedgerID HAVING COUNT(*)>1) d;
SELECT TOP (12) a.RDate,e.EmpCode,e.EmpName,b.BlockName,w.HarvestedNormal,w.HarvestedBorongan,w.PaidNormal,w.PaidBorongan,w.Ha FROM Checkroll.DailyReceiption r JOIN Checkroll.DailyAttendance a ON a.DailyReceiptionID=r.DailyReceiptionID AND a.EstateID=r.EstateID LEFT JOIN Checkroll.CREmployee e ON e.EmpID=a.EmpID LEFT JOIN General.BlockMaster b ON b.BlockID=r.BlockID AND b.EstateID=r.EstateID JOIN Checkroll.DailyReceptionWithTeam w ON w.DailyReceiptionDetID=r.DailyReceiptionDetID WHERE r.EstateID=@EstateID AND a.RDate>=@FromDate AND a.RDate<@ToDate ORDER BY a.RDate DESC,e.EmpCode,b.BlockName;
